const D={up:[1,0],down:[-1,0],left:[0,-1],right:[0,1]};
const S=Math.SQRT1_2;
const Q={up:[-S,0,0,S],down:[S,0,0,S],right:[0,0,-S,S],left:[0,0,S,S]};
function dist(s){return (2-s.r)+(2-s.c);}
function pos(s){return [(s.c-1)*1.1,0.44,(1-s.r)*1.1];}
export function initialState(){return {r:0,c:0,moves:0,hint:null,msg:'Reach the orange goal square.'};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;const s={...state};
if(dist(s)===0)return state;
if(a==='hint'){s.hint=s.r<2?'up':'right';s.msg='Hint: move '+s.hint+'.';return s;}
const d=D[a];if(!d)return state;
const r=s.r+d[0],c=s.c+d[1];
if(r<0||r>2||c<0||c>2){s.msg='Edge of the board: can\'t move '+a+'.';s.hint=null;return s;}
s.r=r;s.c=c;s.moves++;s.hint=null;
if(dist(s)===0)s.msg='You reached the goal in '+s.moves+' moves. Shortest route: 4 moves.'+(s.moves===4?' Perfect!':'');
else s.msg='Moved '+a+'.';
return s;}
export function evaluate({state}){
const s=state||initialState();const p=pos(s);const won=dist(s)===0;
const n={token:{position:p},hintArrow:{visible:!!s.hint&&!won,position:p}};
if(s.hint)n.hintArrow.quaternion=Q[s.hint];
return {nodes:n,readouts:{steps:dist(s),moves:s.moves},goal:{status:won?'won':'playing',message:s.msg}};}
